def write_file(path, content):
    with open(path, "w") as f:
        f.write(content)
    print(f"  wrote {path} ({len(content.splitlines())} lines)")

print("1/9 — app/miniguru/lib/network/MiniguruApi.dart")
write_file('app/miniguru/lib/network/MiniguruApi.dart', 'import \'dart:convert\';\nimport \'dart:typed_data\';\n\nimport \'package:flutter/foundation.dart\' show kIsWeb;\nimport \'package:http/http.dart\' as http;\nimport \'package:image_picker/image_picker.dart\';\nimport \'package:miniguru/database/database_helper.dart\';\nimport \'package:miniguru/models/AuthToken.dart\';\nimport \'package:miniguru/models/User.dart\';\nimport \'package:miniguru/models/ChildProfile.dart\';\nimport \'package:miniguru/models/Projects.dart\';\nimport \'package:path/path.dart\';\nimport \'package:http_parser/http_parser.dart\';\nimport \'package:miniguru/secrets.dart\';\nimport \'package:miniguru/state/sessionState.dart\';\n\n\nclass MiniguruApi {\n  static const String _baseUrl = apiBaseUrl;\n  DatabaseHelper? _db;\n\n  MiniguruApi() {\n    _db = DatabaseHelper();\n  }\n\n  // ========================= AUTHENTICATION =========================\n\n  Future<http.Response> login(String email, String password) async {\n    final url = Uri.parse(\'$_baseUrl/auth/login\');\n    print(\'🔵 Login Request: $url\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(),\n      body: jsonEncode({\'email\': email, \'password\': password}),\n    );\n    _handleResponse(response);\n    if (response.statusCode == 200) {\n      final body = jsonDecode(response.body);\n      print(\'✅ Refresh token received: ${body[\'refreshToken\']?.substring(0, 20)}...\');\n    }\n    return response;\n  }\n\n  Future<http.Response> register(String name, String email, String password,\n      int age, String phoneNumber) async {\n    final url = Uri.parse(\'$_baseUrl/auth/register\');\n    print(\'🔵 Register Request: $url\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(),\n      body: jsonEncode({\n        \'name\': name,\n        \'email\': email,\n        \'password\': password,\n        \'age\': age,\n        \'phoneNumber\': phoneNumber\n      }),\n    );\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<http.Response> requestPasswordReset(String email) async {\n    final url = Uri.parse(\'$_baseUrl/auth/forgot-password\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(),\n      body: jsonEncode({\'email\': email}),\n    );\n    print(\'📦 Reset Response Status: ${response.statusCode}\');\n    return response;\n  }\n\n  Future<http.Response> resetPassword(String token, String newPassword) async {\n    final url = Uri.parse(\'$_baseUrl/auth/reset-password\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(),\n      body: jsonEncode({\'token\': token, \'newPassword\': newPassword}),\n    );\n    print(\'📦 Reset Response Status: ${response.statusCode}\');\n    return response;\n  }\n\n  Future<http.Response> changePassword(String currentPassword, String newPassword) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/change-password\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'currentPassword\': currentPassword, \'newPassword\': newPassword}),\n    );\n    print(\'📦 Change Password Status: ${response.statusCode}\');\n    return response;\n  }\n\n  Future<http.Response> changeLoginId(String currentPassword, String newLoginId) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/change-login-id\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'currentPassword\': currentPassword, \'newLoginId\': newLoginId}),\n    );\n    print(\'📦 Change Login ID Status: ${response.statusCode}\');\n    return response;\n  }\n\n  // ── Public video feed (home screen) ───────────────────────────────────────\n  // Reads from MiniGuru\'s own database via GET /project/feed — replaces the\n  // old direct-YouTube-API approach in youtube_service.dart, which burned\n  // shared YouTube quota on every home-screen load and silently fell back\n  // to placeholder videos on any failure. No auth needed — public feed.\n  Future<List<Map<String, dynamic>>> getVideoFeed({int limit = 50}) async {\n    final url = Uri.parse(\'$_baseUrl/project/feed?limit=$limit\');\n    final response = await http.get(url, headers: _buildHeaders());\n    if (response.statusCode != 200) {\n      throw Exception(\'Failed to load video feed (${response.statusCode})\');\n    }\n    final data = jsonDecode(response.body);\n    final videos = data[\'videos\'];\n    if (videos is List) {\n      return videos.map((v) => Map<String, dynamic>.from(v)).toList();\n    }\n    return [];\n  }\n\n  // Public, no-auth-required project categories — same GET /project/categories\n  // data used at upload time (addDraftScreen.dart via ProjectRepository), but\n  // that path requires a logged-in token. Home screen needs this for BOTH\n  // guests and logged-in users, so this hits the same backend route (which\n  // has no auth middleware at all) directly, same pattern as getVideoFeed().\n  Future<List<Map<String, dynamic>>> getPublicCategories() async {\n    final url = Uri.parse(\'$_baseUrl/project/categories\');\n    final response = await http.get(url, headers: _buildHeaders());\n    if (response.statusCode != 200) {\n      throw Exception(\'Failed to load categories (${response.statusCode})\');\n    }\n    final data = jsonDecode(response.body);\n    if (data is List) {\n      return data.map((c) => Map<String, dynamic>.from(c)).toList();\n    }\n    return [];\n  }\n\n  // ── Suggest a material not in the picker list ─────────────────────────────\n  // No auth required (same public POST /shop/suggest already used by the\n  // shop page\'s "Suggest a product" box) — a child suggesting a material\n  // while planning a project may not always be mid-session-valid, so this\n  // stays open the same way the shop\'s version already is.\n  Future<bool> suggestMaterial({\n    required String suggestion,\n    String? childName,\n    String? category,\n    int? requestedGoinsPrice,\n    String? projectContext,\n  }) async {\n    final url = Uri.parse(\'$_baseUrl/shop/suggest\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(),\n      body: jsonEncode({\n        \'suggestion\': suggestion,\n        if (childName != null) \'childName\': childName,\n        if (category != null) \'category\': category,\n        if (requestedGoinsPrice != null) \'requestedGoinsPrice\': requestedGoinsPrice,\n        if (projectContext != null) \'projectContext\': projectContext,\n      }),\n    );\n    return response.statusCode == 201;\n  }\n\n  // ── Contact verification (email/phone) — optional, on-demand ─────────────\n  // See backend/src/controllers/auth/contactVerificationController.ts for\n  // the full design: unverified contacts just show "Unverified" and can be\n  // verified whenever the person wants; changing a VERIFIED contact needs\n  // an OTP confirmation to the OLD contact (or admin approval if that\'s\n  // unreachable), changing an UNVERIFIED one applies immediately.\n\n  Future<http.Response> sendVerificationOtp(String target) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/verification/send-otp\');\n    return await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'target\': target}),\n    );\n  }\n\n  Future<http.Response> confirmVerificationOtp(String otp) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/verification/confirm-otp\');\n    return await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'otp\': otp}),\n    );\n  }\n\n  Future<http.Response> requestContactChange(String target, String newValue) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/verification/request-change\');\n    return await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'target\': target, \'newValue\': newValue}),\n    );\n  }\n\n  Future<http.Response> confirmContactChangeOtp(String otp) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'User not logged in\');\n    final url = Uri.parse(\'$_baseUrl/auth/verification/confirm-change-otp\');\n    return await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'otp\': otp}),\n    );\n  }\n\n  Future<AuthToken?> refreshToken() async {\n    try {\n      print("🔄 Refreshing tokens...");\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) {\n        print("❌ No refresh token found in database");\n        return null;\n      }\n      final url = Uri.parse(\'$_baseUrl/auth/refresh-token\');\n      final response = await http.post(\n        url,\n        headers: _buildHeaders(),\n        body: jsonEncode({\'refreshToken\': authToken.refreshToken}),\n      );\n      if (response.statusCode != 200) {\n        print(\'❌ Token refresh failed: ${response.statusCode}\');\n        return null;\n      }\n      final newAuthToken = jsonDecode(response.body);\n      await _db!.insertAuthToken(newAuthToken[\'accessToken\']!, authToken.refreshToken);\n      final newToken = await _db!.getAuthToken();\n      print(\'✅ Tokens refreshed successfully\');\n      return newToken;\n    } catch (e) {\n      print(\'❌ Error refreshing token: $e\');\n      return null;\n    }\n  }\n\n  Future<User?> getUserData() async {\n    try {\n      print(\'🔵 [getUserData] Starting user data fetch\');\n      final storedToken = await _db!.getAuthToken();\n      if (storedToken == null) {\n        print(\'❌ [getUserData] No auth token found in storage\');\n        return null;\n      }\n      print(\'✅ [getUserData] Token found: ${storedToken.accessToken.substring(0, 20)}...\');\n      \n      var hasTokenExpired = await _db!.hasTokenExpired();\n      AuthToken? authToken;\n      if (hasTokenExpired) {\n        print(\'⚠️  [getUserData] Token expired, refreshing...\');\n        authToken = await refreshToken();\n        if (authToken == null) {\n          print(\'❌ [getUserData] Token refresh failed\');\n          return null;\n        }\n      } else {\n        print(\'✅ [getUserData] Token valid, proceeding\');\n        authToken = storedToken;\n      }\n      \n      final url = Uri.parse(\'$_baseUrl/me\');\n      print(\'🔵 [getUserData] Calling $url\');\n      print(\'   📌 Authorization: Bearer ${authToken.accessToken.substring(0, 20)}...\');\n      \n      final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n      print(\'✅ [getUserData] Response status: ${response.statusCode}\');\n      print(\'   📦 Response body length: ${response.body.length}\');\n      \n      if (response.statusCode == 200) {\n        var data = jsonDecode(response.body);\n        print(\'✅ [getUserData] Response received: ${data[\'user\'][\'name\']}\');\n        data = data[\'user\'];\n        return User(\n          id: data[\'id\'],\n          name: data[\'name\'],\n          email: data[\'email\'],\n          age: data[\'age\'],\n          score: data[\'score\'] ?? 0,\n          walletBalance: data[\'wallet\']?[\'balance\']?.toDouble() ?? 0.0,\n          scoreHistory: data[\'scoreHistory\'] ?? [],\n          phoneNumber: data[\'phoneNumber\'],\n          totalProjects: data[\'totalProjects\'] ?? 0,\n          isMentor: data[\'isMentor\'] ?? false,\n          guardianEmail: data[\'guardianEmail\'],\n          emailVerified: data[\'emailVerified\'] ?? false,\n          phoneVerified: data[\'phoneVerified\'] ?? false,\n        );\n      } else if (response.statusCode == 401) {\n        print(\'❌ [getUserData] 401 Unauthorized - token invalid\');\n        print(\'   📦 Response: ${response.body}\');\n        return null;\n      } else {\n        print(\'❌ [getUserData] Unexpected status: ${response.statusCode}\');\n        print(\'   📦 Response: ${response.body}\');\n        throw Exception(\'Failed to load user data: ${response.statusCode}\');\n      }\n    } catch (e) {\n      print(\'❌ [getUserData] Error fetching user data: $e\');\n      return null;\n    }\n  }\n\n  Future<http.Response?> logout() async {\n    try {\n      final storedToken = await _db!.getAuthToken();\n      if (storedToken == null) {\n        print(\'ℹ️  No user logged in\');\n        return null;\n      }\n      var hasTokenExpired = await _db!.hasTokenExpired();\n      final authToken = (!hasTokenExpired) ? storedToken : await refreshToken();\n      if (authToken == null) {\n        print(\'❌ Cannot logout - no valid token\');\n        return null;\n      }\n      final url = Uri.parse(\'$_baseUrl/auth/logout\');\n      final response = await http.post(url, headers: _buildHeaders(authToken.refreshToken));\n      _handleResponse(response);\n      await _db!.deleteAuthToken();\n      return response;\n    } catch (e) {\n      print(\'❌ Logout error: $e\');\n      return null;\n    }\n  }\n\n  // ========================= HELPER METHOD =========================\n\n  Future<AuthToken?> _getValidToken() async {\n    try {\n      final storedToken = await _db!.getAuthToken();\n      if (storedToken == null) {\n        print(\'⚠️  No token - user needs to login\');\n        return null;\n      }\n      var hasTokenExpired = await _db!.hasTokenExpired();\n      if (hasTokenExpired) {\n        print(\'⏰ Token expired, refreshing...\');\n        return await refreshToken();\n      }\n      return storedToken;\n    } catch (e) {\n      print(\'❌ Error getting token: $e\');\n      return null;\n    }\n  }\n\n  // ========================= PROJECTS =========================\n\n  Future<http.Response?> getAllProjects({required int page, required int limit}) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/project/all?page=$page&limit=$limit\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<http.Response?> getProjectCategories() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/project/categories\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<http.Response?> getAllProjectsForUser() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/project/\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  /// Asks the backend for a short-lived signed URL to upload a file\n  /// DIRECTLY to Firebase Storage, bypassing Cloud Run\'s hard 32MB request\n  /// body limit entirely (confirmed via a real 413 response — this is a\n  /// platform limit, not something any client-side or Cloud Run config\n  /// change can work around). Returns {\'uploadUrl\':..., \'storagePath\':...}\n  /// or null on any failure.\n  Future<Map<String, String>?> _requestUploadUrl(\n      String filename, String contentType, String kind) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    try {\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/project/request-upload-url\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\n          \'filename\': filename,\n          \'contentType\': contentType,\n          \'kind\': kind,\n        }),\n      ).timeout(const Duration(seconds: 30));\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body) as Map<String, dynamic>;\n        return {\n          \'uploadUrl\': data[\'uploadUrl\'] as String,\n          \'storagePath\': data[\'storagePath\'] as String,\n        };\n      }\n      return null;\n    } catch (_) {\n      return null;\n    }\n  }\n\n  Future<http.Response?> uploadProjectWithMedia(\n    Map<String, dynamic> data,\n    XFile video,\n    XFile? thumbnail,\n  ) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n\n    // ── Step 1: upload the video DIRECTLY to Firebase Storage ───────────\n    // Cloud Run enforces a hard, non-configurable 32MB limit on incoming\n    // request bodies — real videos routinely exceed that. Uploading\n    // straight to Firebase Storage (a separate Google service) completely\n    // bypasses that limit; our own backend\'s request body never carries\n    // the actual video bytes at all.\n    final videoUrlInfo = await _requestUploadUrl(video.name, \'video/mp4\', \'video\');\n    if (videoUrlInfo == null) {\n      return http.Response(\n          jsonEncode({\'error\': \'Could not prepare video upload. Please try again.\'}),\n          500);\n    }\n    Uint8List videoBytes;\n    try {\n      videoBytes = await video.readAsBytes();\n    } catch (e) {\n      return http.Response(\n          jsonEncode({\'error\': \'Could not read the video file: $e\'}), 500);\n    }\n    http.Response videoPut;\n    try {\n      videoPut = await http.put(\n        Uri.parse(videoUrlInfo[\'uploadUrl\']!),\n        headers: {\'Content-Type\': \'video/mp4\'},\n        body: videoBytes,\n      ).timeout(const Duration(minutes: 10));\n    } catch (e) {\n      return http.Response(\n          jsonEncode({\'error\': \'Video upload timed out or lost connection — \'\n              \'please check your internet and try again. ($e)\'}),\n          500);\n    }\n    if (videoPut.statusCode < 200 || videoPut.statusCode >= 300) {\n      return http.Response(\n          jsonEncode({\'error\': \'Video upload failed (storage error ${videoPut.statusCode}). \'\n              \'Please try again.\'}),\n          500);\n    }\n\n    // ── Step 2: same for the thumbnail, if any (non-critical — proceed\n    // without one if this fails) ─────────────────────────────────────────\n    String? thumbnailStoragePath;\n    if (thumbnail != null) {\n      try {\n        final thumbUrlInfo =\n            await _requestUploadUrl(thumbnail.name, \'image/jpeg\', \'thumbnail\');\n        if (thumbUrlInfo != null) {\n          final thumbBytes = await thumbnail.readAsBytes();\n          final thumbPut = await http.put(\n            Uri.parse(thumbUrlInfo[\'uploadUrl\']!),\n            headers: {\'Content-Type\': \'image/jpeg\'},\n            body: thumbBytes,\n          ).timeout(const Duration(seconds: 60));\n          if (thumbPut.statusCode >= 200 && thumbPut.statusCode < 300) {\n            thumbnailStoragePath = thumbUrlInfo[\'storagePath\'];\n          }\n        }\n      } catch (_) {\n        // Thumbnail is non-critical — proceed without one.\n      }\n    }\n\n    // ── Step 3: a small, plain JSON request with just the metadata +\n    // storage paths — comfortably under Cloud Run\'s 32MB limit no matter\n    // how large the actual video is, since the video itself is never in\n    // this request body. ─────────────────────────────────────────────────\n    final url = Uri.parse(\'$_baseUrl/project/\');\n    final body = {\n      \'title\': data[\'title\'],\n      \'description\': data[\'description\'],\n      \'startDate\': data[\'startDate\'],\n      \'endDate\': data[\'endDate\'],\n      \'categoryName\': data[\'categoryName\'],\n      \'materials\': data[\'materials\'],\n      \'videoStoragePath\': videoUrlInfo[\'storagePath\'],\n      if (thumbnailStoragePath != null) \'thumbnailStoragePath\': thumbnailStoragePath,\n      if (data[\'collaboratorIds\'] != null &&\n          (data[\'collaboratorIds\'] as List).isNotEmpty)\n        \'collaboratorIds\': data[\'collaboratorIds\'],\n      // BUGFIX: challengeId was missing from this whitelist, so it never\n      // reached the backend even after transformProject started passing it\n      // through — the "Join a STEAM Challenge" feature silently did nothing.\n      if (data[\'challengeId\'] != null) \'challengeId\': data[\'challengeId\'],\n      \'desiredPrivacyStatus\': data[\'desiredPrivacyStatus\'] ?? \'PUBLIC\',\n    };\n\n    http.Response response;\n    try {\n      response = await http.post(\n        url,\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode(body),\n      ).timeout(const Duration(minutes: 8));\n    } catch (e) {\n      return http.Response(\n          jsonEncode({\'error\': \'The video finished uploading, but finalizing the \'\n              \'project took too long or lost connection. Please try again — \'\n              \'if it keeps happening, contact support. ($e)\'}),\n          500);\n    }\n    _handleResponse(response);\n    return response;\n  }\n\n  /// Looks up another user by their MiniGuru ID (login email) so a child\n  /// can add them as a project collaborator while planning. Returns\n  /// {\'id\':..., \'name\':...} on success, or null if not found / any error.\n  Future<Map<String, dynamic>?> findCollaborator(String miniguruId) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    try {\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/project/find-collaborator/${Uri.encodeComponent(miniguruId.trim())}\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        return jsonDecode(response.body) as Map<String, dynamic>;\n      }\n      return null;\n    } catch (e) {\n      return null;\n    }\n  }\n\n  // ── T-LAB Happenings + STEAM Challenges submission workflow ────────────\n  // Any mentor/school/T-LAB/parent account can submit either. Submissions\n  // land as PENDING until an admin approves them (see communitySubmissionsRoutes.ts).\n  Future<Map<String, dynamic>> submitHappening(Map<String, dynamic> data) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return {\'error\': \'Not logged in.\'};\n    try {\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/happenings\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode(data),\n      );\n      final body = jsonDecode(response.body) as Map<String, dynamic>;\n      if (response.statusCode == 201) return body;\n      return {\'error\': body[\'error\']?.toString() ?? \'Failed to submit happening.\'};\n    } catch (e) {\n      return {\'error\': \'Network error: $e\'};\n    }\n  }\n\n  // audience: \'OWN_SCHOOL\' or \'ALL\'\n  Future<Map<String, dynamic>> submitChallenge(Map<String, dynamic> data) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return {\'error\': \'Not logged in.\'};\n    try {\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/challenges\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode(data),\n      );\n      final body = jsonDecode(response.body) as Map<String, dynamic>;\n      if (response.statusCode == 201) return body;\n      return {\'error\': body[\'error\']?.toString() ?? \'Failed to submit challenge.\'};\n    } catch (e) {\n      return {\'error\': \'Network error: $e\'};\n    }\n  }\n\n  // Public feeds — read by community_screen.dart. Auth is optional but\n  // included when available so /challenges can apply OWN_SCHOOL audience\n  // filtering for the logged-in viewer.\n  Future<List<dynamic>> getHappenings() async {\n    try {\n      final authToken = await _getValidToken();\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/happenings\'),\n        headers: _buildHeaders(authToken?.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final body = jsonDecode(response.body) as Map<String, dynamic>;\n        return (body[\'happenings\'] as List<dynamic>?) ?? [];\n      }\n      return [];\n    } catch (e) {\n      return [];\n    }\n  }\n\n  Future<List<dynamic>> getChallenges() async {\n    try {\n      final authToken = await _getValidToken();\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/challenges\'),\n        headers: _buildHeaders(authToken?.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final body = jsonDecode(response.body) as Map<String, dynamic>;\n        return (body[\'challenges\'] as List<dynamic>?) ?? [];\n      }\n      return [];\n    } catch (e) {\n      return [];\n    }\n  }\n\n  Future<http.Response?> addComment(String projectId, String content) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final response = await http.post(\n      Uri.parse("$_baseUrl/project/$projectId/comment"),\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({"content": content}),\n    );\n    if (response.statusCode == 201) return response;\n    _handleResponse(response);\n    return null;\n  }\n\n  // ========================= PRODUCTS =========================\n\n  Future<http.Response?> getAllProducts() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/products/\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<http.Response?> getProductCategories() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/products/categories/all\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  // ========================= ORDERS =========================\n\n  Future<http.Response?> placeOrder(List<Map<String, dynamic>> data, String address) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/order\');\n    final response = await http.post(\n      url,\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({"products": data, "deliveryAddress": address}),\n    );\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<http.Response?> getOrders() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/order/me\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  // ========================= PAYMENTS =========================\n\n  Future<Map<String, dynamic>?> createOrder(String userId, int amount) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final response = await http.post(\n      Uri.parse("$_baseUrl/payment/create-order"),\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({"userId": userId, "amount": amount}),\n    );\n    if (response.statusCode == 201) return jsonDecode(response.body)["data"];\n    print("Failed to create order: ${response.body}");\n    return null;\n  }\n\n  Future<bool> verifyTransaction(String userId, String transactionId, String razorpayOrderId) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return false;\n    final response = await http.post(\n      Uri.parse("$_baseUrl/payment/verify-order"),\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({"userId": userId, "transactionId": transactionId, "razorpayOrderId": razorpayOrderId}),\n    );\n    if (response.statusCode == 200) {\n      final data = jsonDecode(response.body);\n      return data["success"] ?? false;\n    }\n    print("Failed to verify transaction: ${response.statusCode}");\n    return false;\n  }\n\n  // ========================= WALLET =========================\n\n  Future<Map<String, dynamic>?> fetchWallet() async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final response = await http.get(\n      Uri.parse("$_baseUrl/me/wallet"),\n      headers: _buildHeaders(authToken.accessToken),\n    );\n    if (response.statusCode == 200) return jsonDecode(response.body);\n    print("Failed to fetch wallet data: ${response.body}");\n    return null;\n  }\n\n  // ========================= MATERIALS =========================\n\n  Future<http.Response?> getMaterials({String? categoryId}) async {\n    try {\n      final queryParam = categoryId != null ? \'?categoryId=$categoryId\' : \'\';\n      final url = Uri.parse(\'$_baseUrl/materials$queryParam\');\n      final authToken = await _getValidToken();\n      final response = await http.get(url, headers: _buildHeaders(authToken?.accessToken));\n      _handleResponse(response);\n      return response;\n    } catch (e) {\n      print(\'❌ Failed to fetch materials: $e\');\n      return null;\n    }\n  }\n\n  Future<http.Response?> getMaterialCategories() async {\n    try {\n      final url = Uri.parse(\'$_baseUrl/materials/categories\');\n      final response = await http.get(url, headers: _buildHeaders());\n      _handleResponse(response);\n      return response;\n    } catch (e) {\n      print(\'❌ Failed to fetch material categories: $e\');\n      return null;\n    }\n  }\n\n  // ========================= GOINS =========================\n\n  Future<Map<String, dynamic>?> getGoinsBalance() async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/balance\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) return jsonDecode(response.body);\n      print(\'❌ Failed to get goins balance: ${response.statusCode}\');\n      return null;\n    } catch (e) {\n      print(\'❌ Goins balance error: $e\');\n      return null;\n    }\n  }\n\n  // Real Daily Quest progress (Aug 2026) — the home screen card used to be\n  // hardcoded, always showing "3/5 • +50 pts" for every single user.\n  Future<Map<String, dynamic>?> getDailyQuest() async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/daily-quest\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) return jsonDecode(response.body);\n      return null;\n    } catch (e) {\n      print(\'❌ Daily quest error: $e\');\n      return null;\n    }\n  }\n\n  // Real leaderboard rank — was also hardcoded ("Rank #42") right next to\n  // the fake Daily Quest card, fixed together.\n  Future<int?> getMyRank() async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/my-rank\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        return data[\'rank\'] as int?;\n      }\n      return null;\n    } catch (e) {\n      print(\'❌ My rank error: $e\');\n      return null;\n    }\n  }\n\n  Future<http.Response?> getGoinsHistory({int page = 1, int limit = 20}) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) return null;\n    final url = Uri.parse(\'$_baseUrl/goins/history?page=$page&limit=$limit\');\n    final response = await http.get(url, headers: _buildHeaders(authToken.accessToken));\n    _handleResponse(response);\n    return response;\n  }\n\n  Future<Map<String, dynamic>?> awardGoinsForVideoUpload({required String projectId}) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/goins/award/video-upload\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'projectId\': projectId, \'reason\': \'video_upload\'}),\n      );\n      if (response.statusCode == 200 || response.statusCode == 201) {\n        final data = jsonDecode(response.body);\n        print(\'🎉 Goins awarded for upload: +${data[\'awarded\']} | Balance: ${data[\'newBalance\']}\');\n        return data;\n      }\n      return null;\n    } catch (e) {\n      print(\'❌ Award upload goins error: $e\');\n      return null;\n    }\n  }\n\n  Future<Map<String, dynamic>?> awardGoinsForLike({required String videoId, required String likeCategory}) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/goins/award/like\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'videoId\': videoId, \'likeCategory\': likeCategory, \'reason\': \'like_received\'}),\n      );\n      if (response.statusCode == 200 || response.statusCode == 201) return jsonDecode(response.body);\n      return null;\n    } catch (e) {\n      print(\'❌ Award like goins error: $e\');\n      return null;\n    }\n  }\n\n  Future<Map<String, dynamic>?> awardGoinsForComment({required String videoId}) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/goins/award/comment\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'videoId\': videoId, \'reason\': \'comment_received\'}),\n      );\n      if (response.statusCode == 200 || response.statusCode == 201) return jsonDecode(response.body);\n      return null;\n    } catch (e) {\n      print(\'❌ Award comment goins error: $e\');\n      return null;\n    }\n  }\n\n  Future<Map<String, dynamic>?> checkGoinsBalance(int required) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return {\'sufficient\': false, \'balance\': 0, \'required\': required};\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/check?required=$required\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) return jsonDecode(response.body);\n      return null;\n    } catch (e) {\n      print(\'❌ Check goins error: $e\');\n      return null;\n    }\n  }\n// ─── Goins Top-Up Requests ─────────────────────────────────────\n\n  Future<Map<String, dynamic>?> requestGoinsTopUp({\n    required int amount,\n    String? reason,\n    String? projectDraftContext,\n  }) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return null;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/goins/topup/request\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\n          \'amount\': amount,\n          \'reason\': reason,\n          \'projectDraftContext\': projectDraftContext,\n        }),\n      );\n      if (response.statusCode == 200) return jsonDecode(response.body);\n      print(\'❌ Failed to request Goins top-up: ${response.statusCode}\');\n      return null;\n    } catch (e) {\n      print(\'❌ Goins top-up request error: $e\');\n      return null;\n    }\n  }\n\n  Future<List<dynamic>> getMyGoinsTopUpRequests() async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return [];\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/topup/mine\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        return data[\'requests\'] as List<dynamic>? ?? [];\n      }\n      return [];\n    } catch (e) {\n      print(\'❌ Get my Goins top-up requests error: $e\');\n      return [];\n    }\n  }\n\n  Future<List<dynamic>> getMentorPendingTopUpRequests() async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return [];\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/goins/mentor/topup/pending\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        return data[\'requests\'] as List<dynamic>? ?? [];\n      }\n      return [];\n    } catch (e) {\n      print(\'❌ Get mentor pending top-up requests error: $e\');\n      return [];\n    }\n  }\n\n  Future<bool> decideGoinsTopUp({\n    required String requestId,\n    required bool approve,\n    String? denialReason,\n  }) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return false;\n      final action = approve ? \'approve\' : \'deny\';\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/goins/admin/topup/$requestId/$action\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'denialReason\': denialReason}),\n      );\n      return response.statusCode == 200;\n    } catch (e) {\n      print(\'❌ Decide Goins top-up error: $e\');\n      return false;\n    }\n  }\n  \n  // ========================= VIDEO INTERACTION =========================\n\n  // watchedFraction (0.0-1.0) tells the backend how much of the video was\n  // actually watched — the server rejects the call below its own threshold\n  // (currently 0.7) so a stale/bypassed client can\'t just call this\n  // instantly on open. See unifiedVideoPlayer.dart for when this fires.\n  Future<void> trackVideoView(String videoId, {double watchedFraction = 1.0}) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return;\n      await http.post(\n        Uri.parse(\'$_baseUrl/api/videos/$videoId/view\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'watchedFraction\': watchedFraction}),\n      );\n    } catch (e) {\n      print(\'❌ Failed to track view: $e\');\n    }\n  }\n\n  Future<Map<String, dynamic>> getVideoViews(String videoId) async {\n    try {\n      final response = await http.get(Uri.parse(\'$_baseUrl/api/videos/$videoId/views\'));\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        return {\n          \'totalViews\': data[\'totalViews\'] ?? 0,\n          \'uniqueViewers\': data[\'uniqueViewers\'] ?? 0,\n          \'appViews\': data[\'appViews\'] ?? 0,\n          \'youtubeViews\': data[\'youtubeViews\'] ?? 0,\n        };\n      }\n    } catch (e) {\n      print(\'❌ Failed to get views: $e\');\n    }\n    return {\'totalViews\': 0, \'uniqueViewers\': 0, \'appViews\': 0, \'youtubeViews\': 0};\n  }\n\n  Future<void> likeVideo(String videoId, String category, bool liked) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) throw Exception(\'User not logged in\');\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/api/videos/$videoId/like\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'category\': category, \'liked\': liked}),\n      );\n      if (response.statusCode != 200) throw Exception(\'Failed to update like\');\n    } catch (e) {\n      print(\'❌ Like video error: $e\');\n      rethrow;\n    }\n  }\n\n  Future<Map<String, bool>> getUserVideoLikes(String videoId) async {\n    final empty = {\'aesthetic\': false, \'functional\': false, \'sturdy\': false, \'creative\': false, \'educational\': false};\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return empty;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/api/videos/$videoId/likes/user\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final Map<String, dynamic> data = jsonDecode(response.body);\n        return {\n          \'aesthetic\': data[\'aesthetic\'] ?? false,\n          \'functional\': data[\'functional\'] ?? false,\n          \'sturdy\': data[\'sturdy\'] ?? false,\n          \'creative\': data[\'creative\'] ?? false,\n          \'educational\': data[\'educational\'] ?? false,\n        };\n      }\n    } catch (e) {\n      print(\'❌ Get user likes error: $e\');\n    }\n    return empty;\n  }\n\n  // Throws Exception(realBackendMessage) on failure — e.g. "You\'ve already\n  // commented 2 times on this video..." from the 429 comment-cap response —\n  // instead of silently returning null and hiding why it failed from the\n  // child (same real-error-surfacing convention established after the\n  // July 2026 upload-debugging marathon).\n  Future<Map<String, dynamic>?> postVideoComment(String videoId, String comment) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'You need to be logged in to comment.\');\n    final response = await http.post(\n      Uri.parse(\'$_baseUrl/api/videos/$videoId/comments\'),\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'comment\': comment}),\n    );\n    if (response.statusCode == 201) return jsonDecode(response.body);\n    String message = \'Failed to post comment (${response.statusCode})\';\n    try {\n      final body = jsonDecode(response.body);\n      if (body is Map && body[\'message\'] != null) message = body[\'message\'].toString();\n    } catch (_) {}\n    throw Exception(message);\n  }\n\n  // Edits one of the child\'s own existing comments — used once they\'ve hit\n  // the per-video comment cap. Does not earn any additional Goins.\n  Future<Map<String, dynamic>?> updateVideoComment(String commentId, String comment) async {\n    final authToken = await _getValidToken();\n    if (authToken == null) throw Exception(\'You need to be logged in to edit a comment.\');\n    final response = await http.put(\n      Uri.parse(\'$_baseUrl/api/videos/comments/$commentId\'),\n      headers: _buildHeaders(authToken.accessToken),\n      body: jsonEncode({\'comment\': comment}),\n    );\n    if (response.statusCode == 200) return jsonDecode(response.body);\n    String message = \'Failed to update comment (${response.statusCode})\';\n    try {\n      final body = jsonDecode(response.body);\n      if (body is Map && body[\'message\'] != null) message = body[\'message\'].toString();\n    } catch (_) {}\n    throw Exception(message);\n  }\n\n  Future<List<Map<String, dynamic>>> getVideoComments(String videoId, {int limit = 50}) async {\n    try {\n      final response = await http.get(Uri.parse(\'$_baseUrl/api/videos/$videoId/comments?limit=$limit\'));\n      if (response.statusCode == 200) {\n        final List<dynamic> data = jsonDecode(response.body);\n        return data.cast<Map<String, dynamic>>();\n      }\n    } catch (e) {\n      print(\'❌ Failed to get comments: $e\');\n    }\n    return [];\n  }\n\n  Future<bool> deleteVideoComment(String commentId) async {\n    try {\n      final authToken = await _getValidToken();\n      if (authToken == null) return false;\n      final response = await http.delete(\n        Uri.parse(\'$_baseUrl/api/videos/comments/$commentId\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      return response.statusCode == 200;\n    } catch (e) {\n      print(\'❌ Failed to delete comment: $e\');\n      return false;\n    }\n  }\n\n  // ========================= UTILITIES =========================\n\n  Future<bool> checkConnection() async {\n    try {\n      final url = Uri.parse(\'$_baseUrl/health\');\n      final response = await http.get(url).timeout(const Duration(seconds: 5));\n      return response.statusCode == 200;\n    } catch (e) {\n      print(\'❌ Connection check failed: $e\');\n      return false;\n    }\n  }\n\n  Map<String, String> _buildHeaders([String? accessToken]) {\n    return {\n      \'Content-Type\': \'application/json\',\n      if (accessToken != null) \'Authorization\': \'Bearer $accessToken\',\n      if (SessionState.isChildSession && SessionState.activeChildProfileId != null)\n        \'X-Child-Profile-Id\': SessionState.activeChildProfileId!,\n    };\n  }\n\n  void _handleResponse(http.Response response) {\n    if (response.statusCode >= 400) {\n      print(\'❌ Error: ${response.statusCode} - ${response.reasonPhrase}\');\n      print(\'📦 Response Body: ${response.body}\');\n    } else {\n      print(\'✅ Success: ${response.statusCode}\');\n    }\n  }\n\n  Future<Map<String, dynamic>?> getAnalytics() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/users/me/analytics\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) return jsonDecode(response.body) as Map<String, dynamic>;\n    } catch (e) { print(\'❌ getAnalytics: $e\'); }\n    return null;\n  }\n\n  Future<List<dynamic>?> getBadges() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/users/me/badges\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        return (jsonDecode(response.body))[\'badges\'] as List<dynamic>;\n      }\n    } catch (e) { print(\'❌ getBadges: $e\'); }\n    return null;\n  }\n\n  Future<List<dynamic>?> getNotifications() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/users/me/notifications\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        return (jsonDecode(response.body))[\'notifications\'] as List<dynamic>;\n      }\n    } catch (e) { print(\'❌ getNotifications: $e\'); }\n    return null;\n  }\n\n  Future<bool> uploadProfilePhoto(String base64Photo) async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return false;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/users/me/photo\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'photo\': base64Photo}),\n      );\n      return response.statusCode == 200;\n    } catch (e) { print(\'❌ uploadProfilePhoto: $e\'); }\n    return false;\n  }\n\n  Future<String?> getProfilePhoto() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return null;\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/users/me/photo\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        return (jsonDecode(response.body))[\'photo\'] as String?;\n      }\n    } catch (e) { print(\'❌ getProfilePhoto: $e\'); }\n    return null;\n  }\n\n  // ========================= MENTOR =========================\n  Future<http.Response> registerMentor({\n    required String name,\n    required String email,\n    required String phoneNumber,\n    required String password,\n    required String mentorType,\n    String? institutionName,\n    String? city,\n    String? state,\n  }) async {\n    return await http.post(\n      Uri.parse(\'$_baseUrl/mentor/register\'),\n      headers: {\'Content-Type\': \'application/json\'},\n      body: jsonEncode({\n        \'name\': name,\n        \'email\': email,\n        \'phoneNumber\': phoneNumber,\n        \'password\': password,\n        \'mentorType\': mentorType,\n        if (institutionName != null) \'institutionName\': institutionName,\n        if (city != null) \'city\': city,\n        if (state != null) \'state\': state,\n      }),\n    );\n  }\n\n  // ========================= MENTOR — CHILDREN =========================\n  Future<List<ChildProfile>> getMentorChildren() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return [];\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/mentor/children\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        final list = data[\'children\'] as List<dynamic>;\n        return list.map((e) => ChildProfile.fromMap(e as Map<String, dynamic>)).toList();\n      }\n    } catch (e) { print(\'❌ getMentorChildren: $e\'); }\n    return [];\n  }\n\n  // BUGFIX (Aug 2026): the old flow fetched the MENTOR\'s own projects\n  // (always empty — mentors don\'t upload) for the Children\'s Activity\n  // dashboard. This fetches every project belonging to ANY of the\n  // mentor\'s children directly, in one call.\n  Future<List<Project>> getMentorChildrenProjects() async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return [];\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/mentor/children/projects\'),\n        headers: _buildHeaders(authToken.accessToken),\n      );\n      if (response.statusCode == 200) {\n        final List<dynamic> data = jsonDecode(response.body);\n        return data.map((e) => Project.fromJson(e as Map<String, dynamic>)).toList();\n      }\n    } catch (e) { print(\'❌ getMentorChildrenProjects: $e\'); }\n    return [];\n  }\n\n  Future<Map<String, dynamic>?> addChildProfile({required String name, required int age, String? grade, required String pin}) async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return null;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/mentor/children\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\n          \'name\': name,\n          \'age\': age,\n          if (grade != null) \'grade\': grade,\n          \'pin\': pin,\n        }),\n      );\n      if (response.statusCode == 201) {\n        final data = jsonDecode(response.body);\n        return data[\'credentials\'] as Map<String, dynamic>?;\n      }\n    } catch (e) { print(\'❌ addChildProfile: $e\'); }\n    return null;\n  }\n\n  Future<bool> verifyChildPin(String childId, String pin) async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      if (authToken == null) return false;\n      final response = await http.post(\n        Uri.parse(\'$_baseUrl/mentor/children/$childId/verify-pin\'),\n        headers: _buildHeaders(authToken.accessToken),\n        body: jsonEncode({\'pin\': pin}),\n      );\n      if (response.statusCode == 200) {\n        return (jsonDecode(response.body))[\'valid\'] == true;\n      }\n    } catch (e) { print(\'❌ verifyChildPin: $e\'); }\n    return false;\n  }\n\n  // ========================= CMS (PUBLIC — no auth needed) =========================\n\n  /// Fetches CMS content for a given key from GET /cms/:key.\n  /// Keys: community | about | consultancy | legal_privacy | legal_terms | legal_child_safety\n  Future<Map<String, dynamic>?> getCmsContent(String key) async {\n    try {\n      final response = await http.get(\n        Uri.parse(\'$_baseUrl/cms/$key\'),\n        headers: {\'Content-Type\': \'application/json\'},\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body) as Map<String, dynamic>;\n        final v = data[\'value\']; if (v is String) { try { return Map<String, dynamic>.from(jsonDecode(v) as Map); } catch(_) {} } if (v is Map) return Map<String, dynamic>.from(v as Map); return null;\n      }\n      print(\'⚠️  getCmsContent($key): ${response.statusCode}\');\n    } catch (e) {\n      print(\'❌ getCmsContent($key): $e\');\n    }\n    return null;\n  }\n  // ── GET /users/leaderboard ── top 10 makers + caller rank ───────────────\n  Future<Map<String, dynamic>?> getLeaderboard() async {\n    try {\n      final url = Uri.parse(\'$apiBaseUrl/users/leaderboard\');\n      final authToken = await _db?.getAuthToken();\n      final response = await http.get(url, headers: _buildHeaders(authToken?.accessToken));\n      if (response.statusCode == 200) {\n        return json.decode(response.body) as Map<String, dynamic>;\n      }\n      return null;\n    } catch (e) {\n      print(\'getLeaderboard error: $e\');\n      return null;\n    }\n  }\n\n  // ─── POST /mentor/children/bulk ─────────────────────────────────────────────\n  Future<Map<String, dynamic>?> bulkAddChildren(\n      List<Map<String, dynamic>> children) async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      final response = await http.post(\n        Uri.parse(\'$apiBaseUrl/mentor/children/bulk\'),\n        headers: _buildHeaders(authToken?.accessToken ?? \'\'),\n        body: jsonEncode({\'children\': children}),\n      );\n      if (response.statusCode == 201) {\n        return jsonDecode(response.body) as Map<String, dynamic>;\n      }\n      print(\'bulkAddChildren error: \\${response.statusCode}\');\n      return null;\n    } catch (e) {\n      print(\'bulkAddChildren exception: \\$e\');\n      return null;\n    }\n  }\n\n  Future<Map<String, dynamic>?> emailBulkCredentials(\n      List<Map<String, dynamic>> results) async {\n    try {\n      final authToken = await _db!.getAuthToken();\n      final response = await http.post(\n        Uri.parse(\'$apiBaseUrl/mentor/send-credentials\'),\n        headers: _buildHeaders(authToken?.accessToken ?? \'\'),\n        body: jsonEncode({\'results\': results}),\n      );\n      final body = jsonDecode(response.body) as Map<String, dynamic>;\n      body[\'_ok\'] = response.statusCode == 200;\n      return body;\n    } catch (e) {\n      print(\'emailBulkCredentials exception: \\$e\');\n      return null;\n    }\n  }\n\n\n  // ─── GET /users/me/profile ───────────────────────────────────────────────────\n  Future<Map<String, dynamic>?> getProfile() async {\n    final storedToken = await _db!.getAuthToken();\n    if (storedToken == null) return null;\n    final response = await http.get(\n      Uri.parse(\'$apiBaseUrl/users/me/profile\'),\n      headers: {\'Authorization\': \'Bearer ${storedToken.accessToken}\'},\n    );\n    if (response.statusCode == 200) return jsonDecode(response.body);\n    return null;\n  }\n\n  // ─── PUT /users/me/profile ───────────────────────────────────────────────────\n  Future<bool> updateProfile(Map<String, dynamic> data) async {\n    final storedToken = await _db!.getAuthToken();\n    if (storedToken == null) return false;\n    final response = await http.put(\n      Uri.parse(\'$apiBaseUrl/users/me/profile\'),\n      headers: {\'Authorization\': \'Bearer ${storedToken.accessToken}\',\n                 \'Content-Type\': \'application/json\'},\n      body: jsonEncode(data),\n    );\n    return response.statusCode == 200;\n  }\n\n\n\n  /// Fetches materials for the project linked to a YouTube video ID.\n  /// Returns a list of enriched material maps, or null on error.\n  /// Used by home.dart to show the "Materials used" strip — never blocks UI.\n  Future<List<dynamic>?> getVideoMaterials(String videoId) async {\n    try {\n      if (videoId.isEmpty) return null;\n      final response = await http.get(\n        Uri.parse(\'$apiBaseUrl/api/videos/${Uri.encodeComponent(videoId)}/materials\'),\n        headers: {\'Content-Type\': \'application/json\'},\n      );\n      if (response.statusCode == 200) {\n        final data = jsonDecode(response.body);\n        return data[\'materials\'] as List<dynamic>?;\n      }\n      return null;\n    } catch (_) {\n      return null; // silently ignore — materials strip is optional\n    }\n  }\n\n  // Lets ANY viewer (not just the project\'s own uploader) email themselves\n  // or a parent the materials-to-buy list for a project they\'re watching.\n  Future<bool> sendMaterialsToParent({\n    required String parentEmail,\n    required String projectTitle,\n    required List<Map<String, dynamic>> items,\n    String childName = \'A MiniGuru viewer\',\n  }) async {\n    try {\n      final response = await http.post(\n        Uri.parse(\'$apiBaseUrl/shop/send-to-parent\'),\n        headers: {\'Content-Type\': \'application/json\'},\n        body: jsonEncode({\n          \'childName\': childName,\n          \'parentEmail\': parentEmail,\n          \'projectTitle\': projectTitle,\n          \'items\': items,\n        }),\n      );\n      return response.statusCode == 200;\n    } catch (_) {\n      return false;\n    }\n  }\n\n\n}')

