write_file('app/miniguru/lib/repository/draftsRepository.dart', 'import \'dart:convert\';\nimport \'dart:core\';\n\nimport \'package:image_picker/image_picker.dart\';\nimport \'package:miniguru/database/database_helper.dart\';\nimport \'package:miniguru/models/Draft.dart\';\nimport \'package:miniguru/network/MiniguruApi.dart\';\n\nclass DraftRepository {\n  final _db = DatabaseHelper();\n  final _api = MiniguruApi();\n\n  Future<int> saveDraft(String title, String description, String category,\n      {String? videoId,\n      Map<String, int>? materials,\n      DateTime? startDate,\n      DateTime? endDate,\n      String? childKey}) async {\n    final draft = Draft(\n      title: title,\n      description: description,\n      category: category,\n      materials: materials ?? {},\n      startDate: startDate,\n      endDate: endDate,\n      childKey: childKey,\n    );\n    return await _db.insertDraft(draft);\n  }\n\n  /// Pass [childKey] to only get drafts tagged for a specific identity (the\n  /// logged-in user\'s own account id, or a ChildProfile id during a\n  /// mentor\'s PIN session). Pass [alsoMatchKeys] for any additional\n  /// identities that should also count as "mine" — e.g. a mentor looking\n  /// for a child\'s existing drafts needs to match BOTH the ChildProfile id\n  /// (drafts made during a past PIN session) AND that child\'s own\n  /// linkedUserId (drafts they made logging in independently), since the\n  /// same child can create drafts through either path.\n  /// Drafts saved before this tagging existed have no childKey yet and are\n  /// always included, rather than silently disappearing or leaking only to\n  /// whoever happens to open the app next — see BUGFIX note below.\n  Future<List<Draft>> getDrafts({String? childKey, List<String>? alsoMatchKeys}) async {\n    final all = await _db.drafts();\n    if (childKey == null) return all;\n    final keys = {childKey, ...?alsoMatchKeys};\n    return all.where((d) => d.childKey == null || keys.contains(d.childKey)).toList();\n  }\n\n  Future<void> updateDraft(\n      int id, String title, String description, String category,\n      {String? videoId,\n      Map<String, int>? materials,\n      DateTime? startDate,\n      DateTime? endDate,\n      String? childKey}) async {\n    final draft = Draft(\n      id: id,\n      title: title,\n      description: description,\n      category: category,\n      materials: materials ?? {},\n      startDate: startDate,\n      endDate: endDate,\n      childKey: childKey,\n    );\n    await _db.updateDraft(draft);\n  }\n\n  Future<void> deleteDraft(int id) async {\n    await _db.deleteDraft(id);\n  }\n\n  Future<int> saveOrUpdateDraft(\n      {int? id,\n      required String title,\n      required String description,\n      required String category,\n      Map<String, int>? materials,\n      DateTime? startDate,\n      DateTime? endDate,\n      String? childKey}) async {\n    if (id == null) {\n      return await saveDraft(title, description, category,\n          materials: materials,\n          startDate: startDate,\n          endDate: endDate,\n          childKey: childKey);\n    } else {\n      await updateDraft(id, title, description, category,\n          materials: materials,\n          startDate: startDate,\n          endDate: endDate,\n          childKey: childKey);\n      return -1;\n    }\n  }\n\n  Future<Draft?> getDraftById(int id) async {\n    return _db.getDraftById(id);\n  }\n\n  Future<int> uploadProjects(\n      Map<String, dynamic> project, XFile video, XFile? thumbnail) async {\n    final data = transformProject(project);\n    final response = await _api.uploadProjectWithMedia(data, video, thumbnail);\n\n    if (response != null && response.statusCode == 201) {\n      jsonDecode(response.body);\n      return response.statusCode;\n    } else {\n      // Surface the REAL backend error instead of a generic message — this\n      // was previously discarded entirely, which is why every past failure\n      // (regardless of actual cause) showed the exact same unhelpful text.\n      String detail = \'no response from server\';\n      if (response != null) {\n        detail = \'HTTP ${response.statusCode}\';\n        try {\n          final parsed = jsonDecode(response.body);\n          if (parsed is Map && parsed[\'error\'] != null) {\n            detail = \'${response.statusCode}: ${parsed[\'error\']}\';\n          } else if (response.body.isNotEmpty) {\n            detail = \'${response.statusCode}: ${response.body}\';\n          }\n        } catch (_) {\n          if (response.body.isNotEmpty) {\n            detail = \'${response.statusCode}: ${response.body}\';\n          }\n        }\n      }\n      print(\'Failed to upload project: $detail\');\n      throw Exception(detail);\n    }\n  }\n\n  Map<String, dynamic> transformProject(Map<String, dynamic> project) {\n    List<dynamic> transformedMaterials = project[\'materials\']\n        .entries\n        .map((entry) => {\n              \'productId\': entry.key,\n              \'quantity\': entry.value,\n            })\n        .toList();\n\n    String? formatDate(DateTime? date) {\n      return date?.toIso8601String();\n    }\n\n    Map<String, dynamic> transformedProject = {\n      \'title\': project[\'title\'],\n      \'description\': project[\'description\'],\n      \'startDate\': formatDate(project[\'startDate\']),\n      \'endDate\': formatDate(project[\'endDate\']),\n      \'categoryName\': project[\'category\'],\n      \'videoId\': project[\'videoId\'],\n      \'materials\': transformedMaterials,\n      // Shared/group projects — list of collaborator user IDs, if any\n      // were added while planning. Empty/absent for a normal solo project.\n      \'collaboratorIds\': project[\'collaboratorIds\'] ?? [],\n      // STEAM Challenge join (optional) — BUGFIX: this was previously\n      // dropped here, so a child could pick a challenge in addDraftScreen\n      // and it would silently never reach the backend (no participant\n      // count, no bonus Goins, no error shown). Pass it through if present.\n      if (project[\'challengeId\'] != null) \'challengeId\': project[\'challengeId\'],\n      // Uploader\'s own privacy-status choice — PRIVATE means the video\n      // stays Unlisted on YouTube forever regardless of review outcome.\n      \'desiredPrivacyStatus\': project[\'desiredPrivacyStatus\'] ?? \'PUBLIC\',\n    };\n\n    return transformedProject;\n  }\n}\n')

